FILTER (?year > 1699 && ?year < 1800)
SERVICE wikibase:label {bd:serviceParam wikibase:language "[AUTO_LANGUAGE],mul,en,de,fr,ru"}
} ORDER BY ?authorLabel ?year ?poemLabel

