SELECT DISTINCT ?artist ?artistLabel (SAMPLE(?countryLabel) as ?countryName) ?links (SAMPLE(?benezit_id) AS ?benezit) (SAMPLE(?grove_id) AS ?grove) WHERE {
{ ?artist wdt:P2843 ?benezit_id } UNION { ?artist wdt:P8406 ?grove_id }
  ?artist wikibase:sitelinks ?links FILTER (?links > 0).
  ?artist wdt:P31 wd:Q5.
