  FILTER NOT EXISTS{?enwp schema:about ?artist; schema:inLanguage "en"}
    SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en,mul" }
} GROUP BY ?artist ?artistLabel ?links
