PREFIX  p:    <http://www.wikidata.org/prop/>
PREFIX  pq:   <http://www.wikidata.org/prop/qualifier/>
PREFIX  ps:   <http://www.wikidata.org/prop/statement/>
PREFIX  rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX  schema: <http://schema.org/>
PREFIX  wd:   <http://www.wikidata.org/entity/>
PREFIX  wdt:  <http://www.wikidata.org/prop/direct/>

SELECT  ?person ?personLabel ?personDescription (URI(concat("https://viaf.org/viaf/", ?viaf)) AS ?viaf_link) (URI(concat("https://doi.org/10.1093/ref:odnb/", ?odnb)) AS ?odnb_link) ?image ?url
WHERE
  { ?person  p:P485   _:b0 .
    _:b0     ps:P485  wd:Q1456119 ;
             pq:P973  ?url
    OPTIONAL
      { ?person  wdt:P214  ?viaf }
    OPTIONAL
      { ?person  wdt:P18  ?image }
    OPTIONAL
      { ?person  wdt:P1415  ?odnb }
    OPTIONAL
      { ?person  rdfs:label  ?person__label_value
        FILTER ( lang(?person__label_value) = "en" )
      }
    OPTIONAL
      { ?person  rdfs:label  ?person__label_value
        FILTER ( lang(?person__label_value) = "mul" )
      }
    BIND(if(bound(?person__label_value), ?person__label_value, if(( isURI(?person) && strstarts(str(?person), "http://www.wikidata.org/entity/") ), strafter(str(?person), "entity/"), str(?person))) AS ?personLabel)
    OPTIONAL
      { ?person  schema:description  ?person__description_value
