PREFIX  rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX  schema: <http://schema.org/>
PREFIX  wd:   <http://www.wikidata.org/entity/>

SELECT DISTINCT  ?related ?relatedLabel ?relatedDescription
WHERE
  { VALUES ?target { wd:Q42 }
      { ?target  ?prop  ?related }
    UNION
      { ?related  ?prop  ?target }
    FILTER contains(str(?related), "/entity/Q")
    OPTIONAL
      { ?related  rdfs:label  ?related__label_value
        FILTER ( lang(?related__label_value) = "en" )
      }
    OPTIONAL
      { ?related  rdfs:label  ?related__label_value
        FILTER ( lang(?related__label_value) = "mul" )
      }
    BIND(if(bound(?related__label_value), ?related__label_value, if(( isURI(?related) && strstarts(str(?related), "http://www.wikidata.org/entity/") ), strafter(str(?related), "entity/"), str(?related))) AS ?relatedLabel)
    OPTIONAL
      { ?related  schema:description  ?related__description_value
        FILTER ( lang(?related__description_value) = "en" )
      }
    BIND(?related__description_value AS ?relatedDescription)
  }
ORDER BY ucase(?relatedLabel)

