#title:Manuscripts in the Taylor-Schechter Collection with IIIF links
#defaultView:ImageGrid{"hide": ["?image","?placeholder"]}
SELECT DISTINCT ?qLabel ?image (URI(CONCAT('https://tools.wmflabs.org/mirador/?manifest=', STR(?iiif))) AS ?q) ?placeholder WHERE {
  ?item wdt:P195 wd:Q132817387
   OPTIONAL {?item wdt:P6108 ?iiif}
  OPTIONAL{ ?item wdt:P18 ?img }
BIND (IF(BOUND(?img), ?img, <http://commons.wikimedia.org/wiki/Special:FilePath/International%20Image%20Interoperability%20Framework%20logo.png>) AS ?image)
BIND (IF(BOUND(?img), 0, 1) AS ?placeholder)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en,mul". ?item rdfs:label ?qLabel }
} ORDER BY ?placeholder

