#title: Things depicted in art works of the Khalili Collections
SELECT (URI(CONCAT("https://tools.wmflabs.org/reasonator/?q=", STRAFTER(STR(?depicted),"/entity/") )) as ?q) (?nameplusdesc AS ?qLabel) (SAMPLE(?image) AS ?img) WHERE {
