    OPTIONAL{?part wdt:P180 ?thing. ?thing rdfs:label ?label FILTER(lang(?label)="en")}
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
} GROUP BY ?part ?partLabel ?inv
ORDER BY UCASE(?inv)

