  OPTIONAL{ ?item wdt:P6216 wd:Q19652 . BIND("PDyes" as ?pd)}
  BIND(IF(BOUND(?copy), IF(BOUND(?pd), "Disputed", "Copyrighted"), IF(BOUND(?pd), "Public Domain", "Unclear") ) AS ?status)
} GROUP BY ?status
ORDER BY DESC(?count)

